// Уроци и задачи за Кортеж.
// Решенията (solution / answer) остават САМО на сървъра — build скриптът ги маха от публичния файл.
//
// Видове задачи:
//   kind:'choice'  — тестов въпрос (options, answer = индекс на верния)
//   kind:'sql', type:'select' — сравнява се резултатът от последния SELECT
//   kind:'sql', type:'modify' — след заявките на ученика се пуска `check` и се сравнява таблицата
//   params: [ {...}, {...} ] — параметризирана заявка, проверява се с всеки набор стойности

const ex = (db, sql) => `<pre class="ex" data-db="${db}">${sql.trim().replace(/&/g, '&amp;').replace(/</g, '&lt;')}</pre>`;
const note = (html) => `<div class="note">${html}</div>`;
const warn = (html) => `<div class="note warn">${html}</div>`;
const syn = (s) => `<pre class="syntax">${s.trim().replace(/</g, '&lt;')}</pre>`;

